---@param callback fun(packetId:integer, packetData:table|string):void
local CommonPacketHandler = function(callback)
    local handlerCallback = callback
    ---@param packetId integer
    ---@param reader System.IO.BinaryReader
    ---@param bodyLen integer
    ---@param source System.Net.IPEndPoint
    return function(packetId, reader, bodyLen, source)
        AppService:GetInstance():RemoveCache(packetId)
        local jsonStr = KNManager.ReadPayloadString(reader, bodyLen)
        if not string.isEmpty(jsonStr) then
            local data = table.deserialize(jsonStr)
            if handlerCallback then
                handlerCallback(packetId, data or jsonStr)
            end
        end
    end
end

