function AppService:__init()
    ---用来处理120s发送一次的防沉迷的逻辑
    applicationEventHandler.onSuspend = Bind(self, self.OnAppSuspendHandler)
    applicationEventHandler.onLowMemory = Bind(self, self.OnAppLowMemoryHandler)
    applicationEventHandler.onQuit = Bind(self, self.OnAppQuitHandler)
    self.isOpenAntiIndulgence = false
    ---@type System.DateTime
    self.preClientTime = 0
    ---@type System.DateTime
    self.playerStartTime = 0
    ---@type System.DateTime
    self.takePingTime = 0
    ---@type integer
    self.elapsedDelta = 0
    self.friendIsBusy = false
    self.friendPVPData = {}
    KNManager.onConnect = function(isSuccess, message)
        self:OnTcpConnectHandler(isSuccess, message)
    end
    KNManager.onDisconnect = function()
        self:OnTcpDisconnectHandler()
    end
    KNManager.onError = function(message)
        self:OnTcpErrorHandler(message)
    end
    ---聊天用的tcp
    ---@type Social
    self.socialLine = nil
    ----计算开始时间
    self.tickStart = os.time()
    self.isFinished = false
    self:RefreshLadderPvpTime()
    ---@type System.DateTime
    self.chatPreClientTime = 0
    self.pingTime = 0
    self.waitAckQueue = {}

    local logFileDirectory
    -- 本地记录日志
    local isEditor = CS.UnityEngine.Application.isEditor
    local dataPath = CS.UnityEngine.Application.dataPath
    local persistentDataPath = CS.UnityEngine.Application.persistentDataPath
    local fileName = string.format("%s_Main_Tcp_Log.txt", os.date("%m_%d", os.time()))
    if isEditor then
        local ts = string.reverse(dataPath)
        local _, i = string.find(ts, "/")
        local m = string.len(ts) - i + 1
        local dirPath = string.sub(dataPath, 1, m)
        self.logFilePath = dirPath.."Product/"..fileName
        logFileDirectory = dirPath.."Product/"
    else
        self.logFilePath = persistentDataPath.."/"..fileName
        logFileDirectory = persistentDataPath.."/"
    end
    
    -- 删除过期的日志文件
    self:RemoveExpirationLogFile(logFileDirectory, LogFileExpirationTime)
end

