function AppService:RefreshLadderPvpTime()
    local pattern = "(%d+):(%d+):(%d+)"
    local _getTimeStamp = function(id)
        ---@type LadderParameterVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', id)
        local timeList = parse_strings(vo.num, ";")
        local times = {}
        for i, time in ipairs(timeList) do
            local hour, min, sec = time:match(pattern)
            local t = GameUtils.GetServerTimeStamp(hour, min, sec)
            table.insert(times, t)
        end
        return times
    end
    ---天梯竞技场开启时间节点的处理, 起始时间
    self.ladderStartTimestamp = _getTimeStamp(2)
    self.ladderEndTimestamp = _getTimeStamp(3)
    self.ladderOpenTimes = #self.ladderStartTimestamp
end

