--- 应用程序挂起
---@param seconds number
function AppService:OnAppSuspendHandler(seconds)
    if seconds < 0 then
        self:StopTCP()
        KNManager.onPing = nil
        KNManager.onUpdate = nil
        ---程序挂起，注释通知
        Events.Broadcast(Constants.EventNames.ONAPP_TO_BG)
    else
        ---恢复事件
        KNManager.canRetry = true
        self:DoAppResume()
        Events.Broadcast(Constants.EventNames.ONAPP_TO_FG)
    end
end

function AppService:OnAppLowMemoryHandler()
end

--- 应用程序退出
function AppService:OnAppQuitHandler()
    self.recoveryValue = nil
    kTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
    Events.Broadcast(Constants.EventNames.ONAPPQUIT)
    self:StopTCP()
    self:EnableTcpWeakAnime(false)
    self:UpdateTcpWeakAnime_(false)
    ---退出应用时发送一个请求
    applicationEventHandler.onSuspend = nil
    applicationEventHandler.onLowMemory = nil
    applicationEventHandler.onQuit = nil
    KNManager.onPing = nil
    KNManager.onUpdate = nil
    KNManager.onConnect = nil
    KNManager.onDisconnect = nil
end

function AppService:DoAppResume()
    self:StartTCP()
end


