---移动平台的体力恢复的本地通知
function AppService:MobileHPRecoverNotification()
    if kTool.UNITY_ANDROID() or kTool.UNITY_IOS() then
        if not self:IsOpenNotification() then
            return
        end
        if not isNull(self.recoveryValue) then
            ---计算恢复满需要的时间
            if self.recoveryValue.Current < self.recoveryValue.Max then
                ----需要体力恢复进度
                local offset = self.recoveryValue.Max - self.recoveryValue.Current
                local seconds = offset * self.recoveryValue.RecoveryInterval
                ---@type Game.Native.MobileNotification.NotificationManager
                local manager = kTool.GetOrAddComponent(UIModule.RootCanvas.gameObject, typeof(NotificationManager))
                if not manager.Initialized then
                    manager:Initialize(NotificationChannel(Application.identifier, "猫之城", "猫之城"))
                end
                manager.mode = NotificationManager.OperatingMode.QueueAndClear
                ----先移除一次
                manager:CancelNotification(HP_NOTIFICATION_ID)
                if kTool.UNITY_ANDROID() then
                    local AndroidGameNotification = CS.Game.Native.MobileNotification.Android.AndroidGameNotification
                    ---@type Game.Native.MobileNotification.Android.AndroidGameNotification
                    local notification = AndroidGameNotification()
                    notification.Id = HP_NOTIFICATION_ID
                    notification.Title = localize("您的体力已满")
                    notification.Body = localize("您的体力已满，快去看看吧")
                    notification.DeliveredChannel = Application.identifier
                    --notification.DeliveryTime = CS.System.DateTime.Now:AddSeconds(seconds)
                    notification.DeliveryTime = CS.Engine.Http.TimeZoneUtils.GetDeliveryTime(CS.System.TimeSpan.FromSeconds(seconds))
                    manager:ScheduleNotification(notification)
                else
                    local IosGameNotification = CS.Game.Native.MobileNotification.iOS.IosGameNotification
                    ---@type Game.Native.MobileNotification.iOS.IosGameNotification
                    local notification = IosGameNotification()
                    notification.Id = HP_NOTIFICATION_ID
                    notification.Title = localize("您的体力已满")
                    notification.Body = localize("您的体力已满，快去看看吧")
                    notification.CategoryIdentifier = Application.identifier
                    notification.DeliveryTime = CS.Engine.Http.TimeZoneUtils.GetDeliveryTime(CS.System.TimeSpan.FromSeconds(seconds))
                    manager:ScheduleNotification(notification)
                end
            end
        end
    end
end


