local d = require('Frame.date')
--- 开始连接tcp
---@param isFirstTime boolean
function AppService:StartTCP(isFirstTime)
    isFirstTime = checkBool(isFirstTime)
    self:ClearPacketHandler()

    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if isNull(playerComp) then
        return
    end
    local playerDojo = playerComp.playerDojo
    local serverTime = playerDojo:GetServerTime()
    local now_table = timestamp_to_time(serverTime)
    local now = d(now_table.year, now_table.month, now_table.day, now_table.hour, now_table.min, now_table.sec)
    self._curDate = d(now_table.year, now_table.month, now_table.day, Hour)
    local t = d.diff(now, self._curDate)
    if t:spanseconds() < 0 then
        self._leftFreshSeconds = math.abs(t:spanseconds()) * 1000 + 1000 --保险
    else
        self._leftFreshSeconds = OneDay - t:spanseconds() * 1000 + 1000 ---保险
    end
    if isFirstTime then
        self.takePingTime = KNManager.clientTime
        ----第一次check_in进入时的倒计时的逻辑处理
        local recoveryAmount = 1
        self.recoveryValue = RecoveryValue(checkNumber(playerDojo.hpLimit),
                checkNumber(playerDojo.hp),
                checkNumber(playerDojo.hpRecoverSeconds),
                recoveryAmount, checkNumber(playerDojo.nextHpSeconds))
        self.recoveryValue.OnValueRecovery = function(amount)
            playerDojo.hp = checkNumber(playerDojo.hp) + recoveryAmount--self.recoveryValue.Current ---当前值
            Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, checkNumber(Constants.Currency.HpId))
        end
        self:MobileHPRecoverNotification()
        ---@type Engine.Modules.Atlas.SpriteAtlasManager
        local spriteAtlasMgr = CS.Engine.Modules.Atlas.SpriteAtlasManager.Instance()
        if spriteAtlasMgr and spriteAtlasMgr.LoadAtlasConfigData then
            spriteAtlasMgr:LoadAtlasConfigData()
        end
        local SocialLine = import('Game.OverseaChat.SocialLine')
        self.socialLine = SocialLine()
        self.socialLine:ConnectLobbyServer(playerDojo.chatHost)
    end

    local tcpHost = playerDojo.tcpHost
    if isNull(playerComp) or string.isEmpty(tcpHost) then
        return
    end

    local CommonEventPacketHandler = CommonPacketHandler(function(packetId, packetData)
        Events.Broadcast(Constants.EventNames.ReceivePacketSuccess, packetId, packetData)
    end)
    for _, packetId in ipairs(CommonPacketListens) do
        KNManager.SetPacketHandler(packetId, CommonEventPacketHandler)
    end

    -- 天梯 服务器通知匹配结果
    KNManager.SetPacketHandler(Packets.LadderMatchResult, CommonPacketHandler(function(packetId, packetData)
        local matchResult  = checkInt(packetData.result)
        if matchResult == 1 then
            local LadderTicketId = 3000010
            GoodsUtils.DrawRewards({ [1] = { goodsId = LadderTicketId, num = -1} }, true)
            print("天梯扣票")
        end
        Events.Broadcast(Constants.EventNames.PVPMatchResult, packetId, packetData)
    end))

    -- 天梯 服务器通知取消对局
    KNManager.SetPacketHandler(Packets.LadderCancelBattle, CommonPacketHandler(function(packetId, packetData)
        local LadderTicketId = 3000010
        GoodsUtils.DrawRewards({ [1] = { goodsId = LadderTicketId, num = 1} }, true)
        print("天梯补票")
        if BattleViewMgr then
            -- 已经进入战斗了，退出战斗
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome)
        else
            -- 匹配界面还未关闭，通知匹配界面关闭
            Events.Broadcast(Constants.EventNames.PVPCancelBattle)
        end
    end))

    KNManager.SetPacketHandler(Packets.KickOutPacketId, CommonPacketHandler(function(packetId, packetData)
        if packetData.playerId and packetData.udid then
            if checkInt(packetData.playerId) == checkInt(playerDojo.playerId) and DeviceID.DeviceUDID == packetData.udid then
                CS.Engine.Network.KNManager.canRetry = false
                if  self.socialLine then
                    local gameObject = self.socialLine:GetSocialRelayGameObject()
                    CfUtils.SetActive(gameObject, false)
                end
                AppService:GetInstance():Delete()
                ---同一个角色踢人的操作
                GameUtils.SecondConfirm(localize("同一账号在不同的设备上登录"), function()
                    Application.Quit()
                end, function()
                    Application.Quit()
                    return true
                end)
            end
        end
    end))
    KNManager.SetPacketHandler(Packets.ForbidPacketId, CommonPacketHandler(function(packetId, packetData)
        if packetData.playerId and packetData.udid then
            if checkInt(packetData.playerId) == checkInt(playerDojo.playerId) and DeviceID.DeviceUDID == packetData.udid then
                CS.Engine.Network.KNManager.canRetry = false
                if  self.socialLine then
                    local gameObject = self.socialLine:GetSocialRelayGameObject()
                    CfUtils.SetActive(gameObject, false)
                end
