                GameUtils.SecondConfirm(localize("您的账号登录异常，请重新登录！"), function()
                    Application.Quit()
                end, function()
                    Application.Quit()
                    return true
                end)
            end
        end
    end))
    
    KNManager.SetPacketHandler(Packets.PaidCheckIn, CommonPacketHandler(function(packetId, packetData)
        ---@type PlayerComponent
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        playerComp:GetPlayerDojo():UpdatePaidCheckin(packetData)
    end))
    KNManager.SetPacketHandler(Packets.CheckCanPlayPacketId, CommonPacketHandler(function(packetId, packetData)
        if packetData.canPlay then
            playerDojo.canPlay = checkInt(packetData.canPlay)
