                            self.isOpenAntiIndulgence = false;
                        end
                    }))
                    self.isOpenAntiIndulgence = true
                end
            end
        end
    end))

    KNManager.SetPacketHandler(Packets.CommonError, CommonPacketHandler(function(packetId, packetData)
        if type(packetData) == 'table' then
            GameUtils.Toast(tostring(packetData.msg))
            Events.Broadcast(Constants.EventNames.CommonErrorEventName, packetData)
