        end
        if packetData.unReceivedRegress and checkInt(packetData.unReceivedRegress) == 0 then
            Events.Broadcast(Constants.EventNames.ActivityDialogRefresh)
        end

        -- 累充红点刷新通知
        if packetData.unMallAccmulativePay and checkInt(packetData.unMallAccmulativePay) == 0 then
            Events.Broadcast(Constants.EventNames.StoreAccumulativePayRefresh)
        end

        if packetData.unOverseaClubGvgTask and checkInt(packetData.unOverseaClubGvgTask) == 0 then
