    ---@type TriggerGiftComponent
    local triggerGiftComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TriggerGiftComponent)
    KNManager.SetPacketHandler(Packets.TriggerGiftId, function(packet, reader, len, source)
        triggerGiftComp:TriggerCacheGiftReq()
        xRecord.record('3-022')
    end)

    ---不再处理玩家信息中的长连接
    -- KNManager.SetPacketHandler(Packets.PlayerInfo, Bind(self, self.OnPlayerInfoHit))

    -------------------------------------------------
    -- 临时切磋
    KNManager.SetPacketHandler(Packets.ReceivePVPRequire, CommonPacketHandler(function(packetId, packetData)
