            EnterPVPBattle(packetData)
        end
    end))

    -------------------------------------------------
    -- 好友PVP
    KNManager.SetPacketHandler(Packets.FriendReceivePVPRequire, CommonPacketHandler(function(packetId, packetData)
        self.friendPVPData = packetData
        Events.Broadcast(Constants.EventNames.FriendPVPPrompt, packetData.oppoId)
    end))

    KNManager.SetPacketHandler(Packets.FriendReceivePVPAccept, CommonPacketHandler(function(packetId, packetData)
        local result = checkInt(packetData.result)
        if result == 0 then
            UIRaycastBlocker:AddCondition("ReceivePVPAccept")
