---OnLadderPvpUpdate
---实时pvp的更新计时的逻辑
function AppService:OnLadderPvpUpdate()
    local delta = os.time() - self.tickStart
    if delta >= 1 then
        ---1秒计时一次
        self.tickStart = os.time()
        ---@type PlayerComponent
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if not isNull(playerComp) then
            ---@type PlayerDojo
            local playerDojo = playerComp.playerDojo
            local serverTime = playerDojo:GetServerTime()
            local isInLadderOpenTime, ladderEndTime = self:IsInLadderOpenTime(serverTime)
            if isInLadderOpenTime then
                self.isFinished = false
                ---pvp周期开始了
                if Events.HasListener(Constants.EventNames.PVP_LADDER_TICK) then
                    Events.Broadcast(Constants.EventNames.PVP_LADDER_TICK, ladderEndTime - serverTime)
                end
            else
                if not self.isFinished then
                    Events.Broadcast(Constants.EventNames.PVP_LADDER_TICK, 0)
                end
                self.isFinished = true
            end

            ---处理客户端的红点倒计时
            --playerComp:UpdateTowerRewPoint(Constants.SystemToggleIds.Id2015)
        end
    end
end

function AppService:IsInLadderOpenTime(serverTime)
    for i = 1, self.ladderOpenTimes, 1 do
        if self.ladderStartTimestamp[i] <= serverTime and serverTime <= self.ladderEndTimestamp[i] then
            return true, self.ladderEndTimestamp[i]
        end
    end
    return false
end

---StartManageTip 开始弹窗
---@param packetData table  服务器数据包
---@param needCache boolean 是否需要缓存  当时不触发 要到主界面才触发
function AppService:StartManageTip(packetData, needCache)
    self.MessageTips = {}
    self.timerMessageTips = {}
    self.cacheMessageTips = {}
    for i, v in pairs(packetData) do
        if ManageTipsKeyToId[i] then
            if v <= 0 then
                if v == 0 then
                    if needCache or CfUtils.IsInBattle() then
                        table.insert(self.cacheMessageTips, { key = i, id = ManageTipsKeyToId[i] })
                    else
                        table.insert(self.MessageTips, { key = i, id = ManageTipsKeyToId[i] })
                    end
                end
            else
                table.insert(self.timerMessageTips, { key = i, id = ManageTipsKeyToId[i], time = v })
            end
        end
    end

    self:StartPopMessageTip()

    table.sort(self.timerMessageTips, function(a, b)
        return a.time < b.time
    end)
    ---只缓存那些马上触发的 在倒计时的 只用断定在不在战中
    self:StartTimerMessageTip()
end

function AppService:StartPopMessageTip()
    if table.count(self.MessageTips or {}) > 0 then
        self.isPlaying = true
        GameUtils.ShowManageTips(self.MessageTips[1].id)
        self:RemoveCdTimer(self.waitCdTimer)
        self.waitCdTimer = CDTimerModule:AddCD(3, function(i, t)
            table.remove(self.MessageTips, 1)
            self:StartPopMessageTip()
        end)
    else
        self.isPlaying = false
        self:RemoveCdTimer(self.waitCdTimer)
    end
end

function AppService:StartCacheMessageTip()
    for i, v in pairs(self.cacheMessageTips or {}) do
        table.insert(self.MessageTips, v)
    end
    self.cacheMessageTips = {}
    self:StartPopMessageTip()
end

function AppService:StartTimerMessageTip()
    self:RemoveCdTimer(self.cacheMessageTimer)
    if table.count(self.timerMessageTips) > 0 then
        self.cacheMessageTimer = CDTimerModule:AddCD(self.timerMessageTips[1].time, function(i, t)
            ---有可能这会有正在弹出的Tips
            local data = self.timerMessageTips[1]
            table.remove(self.timerMessageTips, 1)
            if CfUtils.IsInBattle() then
                table.insert(self.cacheMessageTips, data)
            else
                table.insert(self.MessageTips, data)
                ---如果没有在播放 就播放一下
                if not self.isPlaying then
                    self:StartPopMessageTip()
                end
            end
            ---重新开始计算下一个的时间
            self:StartTimerMessageTip()
        end)
    end
end

function AppService:RemoveCdTimer(timer)
    if not isNull(timer) then
        CDTimerModule:RemoveCD(timer)
        timer = nil
    end
end
---清除一下弹窗信息
function AppService:ClearManageTip()
    self:RemoveCdTimer(self.waitCdTimer)
    self:RemoveCdTimer(self.cacheMessageTimer)
    self.MessageTips = nil
    self.timerMessageTips = nil
    self.cacheMessageTips = nil
    Events.Broadcast("RemoveMessageTipByExitGame")
end

