--- 清除包处理器
function AppService:ClearPacketHandler()
    if KNManager.client then
        KNManager.client.packetHandlers:Clear()

        local tcpProtocolType = KNManager.client.protocol:GetType()
        if not isNull(tcpProtocolType:GetProperty("OnSendLog")) then
            KNManager.client.protocol.OnSendLog = nil
        end
        if not isNull(tcpProtocolType:GetProperty("OnTakeLog")) then
            KNManager.client.protocol.OnTakeLog = nil
        end
        if not isNull(tcpProtocolType:GetProperty("OnInfoLog")) then
            KNManager.client.protocol.OnInfoLog = nil
        end
    end
end

