--- 发送tcp请求数据
---@param packetId number
---@param data table
function AppService:SendTcpData(packetId, data, skipCache)
    if not (isNotNull(skipCache) and skipCache == 1) then
        self:AddCache(packetId, data)
    end
    if not KNManager.isConnected then
        GameUtils.Toast(localize('网络未连接，数据发送失败'))
        return
    end
    local commonData = table.deserialize(requestMeta:ToJson())
    CfUtils.AddAreaIdRequest(commonData)
    if isTable(data) then
        table.merge(commonData, data)
    end
    self:TcpLog(LOG_TYPE.SEND, data, packetId)
    ---@type System.IO.BinaryWriter
    local writer = KNManager.BeginSend(packetId)
    KNManager.WritePayloadString(writer, table.serialize(commonData))
    KNManager.EndSend()
end

--- 连接成功或者失败时
---@param isSuccess boolean
---@param message string
function AppService:OnTcpConnectHandler(isSuccess, message)
    if isSuccess then
        self:TcpLog(LOG_TYPE.INFO, 'connected and verified.')
        self.takePingTime = KNManager.clientTime
        self:UpdateTcpWeakAnime_(false)
        Events.Broadcast(Constants.EventNames.GAME_TCP_CONNECT)
        self:ResendCache()
        self:SendFriendPVPReconnect()
    else
        self:TcpLog(LOG_TYPE.INFO, 'connect fail : ' .. tostring(message))
    end
    KNManager.TryTimes = 17280 ---测试3次，每次连接后重置下这个值
    KNManager.canRetry = false
end

--- 收到断连或者手动断连
function AppService:OnTcpDisconnectHandler()
    self:TcpLog(LOG_TYPE.INFO, 'receive disconnect or manual.')
    Events.Broadcast(Constants.EventNames.GAME_TCP_DISCONNECT)
    self:UpdateTcpWeakAnime_(true)
    ---重试3次都不能连接时提示一个界面
    if KNManager.TryTimes < 0 then
        KNManager.canRetry = false
        GameUtils.Toast(localize('重试3次连接都失败了')) --重试3次连接都失败了
    else
        KNManager.canRetry = true ---测试3次，每次连接后重置下这个值
    end
end

--- 收到错误消息
---@param message string
function AppService:OnTcpErrorHandler(message)
    local errorMsg = checkString(message)
    local errorData = table.deserialize(errorMsg)
    if errorData then
        errorMsg = checkString(errorData.msg)
    end
    GameUtils.Toast(errorMsg .. " T⌓T tcp")
    self:TcpLog(LOG_TYPE.INFO, 'receive error : ' .. errorMsg)
end

--- 收到心跳信息
---@param ipEndPoint System.Net.IPEndPoint
---@param ping number
function AppService:OnTcpPingHandler(ipEndPoint, ping)
    -- self:TcpLog(LOG_TYPE.INFO, 'receive ping : ' .. tostring(ping))
    self.pingTime = ping
    self.takePingTime = KNManager.clientTime
    self:UpdateTcpWeakAnime_(false)
end

---处理聊天服务器心跳检测
function AppService:OnLobbyClientUpdateHandler()
    local clientTime = KNManager.clientTime
    if clientTime > (self.chatPreClientTime + ChatHeartbeatDelta) then
        self.chatPreClientTime = clientTime  -- 记录前一次的时间记录
        Events.Broadcast(Constants.EventNames.OVERSEA_CHAT_HEARTBEAT)
    end
end

--- 不断更新的逻辑处理，用来处理定时任务
function AppService:OnKNMgrUpdateHandler()
    local clientTime = KNManager.clientTime
    ---不满足 Threshold 没必要每次new 个Date
    if self._leftFreshSeconds > Threshold then
        self._leftFreshSeconds = self._leftFreshSeconds - math.floor((os.time() - self.tickStart) * 1000)
    else
        self._leftFreshSeconds = OneDay
        ---@type PlayerComponent
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local playerDojo = playerComp.playerDojo
        local serverTime = playerDojo:GetServerTime()
        local now_table = timestamp_to_time(serverTime)
        self._curDate = d(now_table.year, now_table.month, now_table.day, Hour)
        self:ResetCache()
    end

    if KNManager.isActive and KNManager.isConnected then
        if clientTime > (self.preClientTime + CheckCanPlayTimeDelta) then
            self.preClientTime = clientTime  -- 记录前一次的时间记录
            self:SendTcpData(Packets.CheckCanPlayPacketId)
        end
        if clientTime > (self.playerStartTime + CheckPlayerInfoTimeDelta) then
            self.playerStartTime = clientTime  -- 记录前一次的时间记录
            self:SendTcpData(Packets.PlayerInfo)
        end
    end

    -- socket retry check
    if KNManager.isActive then
        if clientTime > (self.takePingTime + CheckTcpWeakTimeDelta) then
            self:UpdateTcpWeakAnime_(true)
        end
        if clientTime > (self.takePingTime + 20000) then
            -- 先改成20s 等解决加载问题
            --if clientTime > (self.takePingTime + CheckTcpRetryTimeDelta) then  -- 等待2次ping的周期还未响应的话
            -- 当 DisconnectHandler 时标记为 true，然后 KNManager.Update 会满足条件重连
            -- 但是重连没成功，那么就不会执行 ConnectHandler 的标记回 false，
            -- 所以太长时间连接未应答的话，这里重新标记为 false，防止 KNManager.Update 中的重连 和 这里的重连 同时生效而重复重连
            if KNManager.canRetry then
                KNManager.canRetry = false  -- 这一帧只做标记，因为判断条件没差异，所以下一帧再进来就会执行重连
            else
                self.takePingTime = clientTime  -- 记录前一次的时间记录
                self:StopTCP()
                self:DoAppResume()
            end
        end
    end

    -- check pingDelta changed
    if TcpPingDeltaTime ~= KNManager.client.PingDeltaTime then
        TcpPingDeltaTime = KNManager.client.PingDeltaTime
        CheckTcpWeakTimeDelta = TcpPingDeltaTime * 1.5
        CheckTcpRetryTimeDelta = TcpPingDeltaTime * 2
    end

    -- recovery update
    if not isNull(self.recoveryValue) then
        self.recoveryValue:UpdateTimeNow()
    end
    if not isNull(self.recoveryValueFreeHp) then
        self.recoveryValueFreeHp:UpdateTimeNow()
    end
    self:TrialUpdateCallback()

end

function AppService:ResetCache()
    if GameUtils == nil or ECSComponentType == nil then
        return
    end
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    cardComp:ResetCache()
    ---每天5点的刷新逻辑
    ---重置下实时pvp的时间节点
    self:RefreshLadderPvpTime()
    ---处理入职福利
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComp then
        ---@type PlayerDojo
        local playerDojo = playerComp.playerDojo
        if playerDojo and isSet(playerDojo.entryWelfareInfo, "status") then
            ---强制处理刷新一次
            GameUtils.Request(Interfaces.OverseaActivityEntryWelfare, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = checkTable(response.data)
                    playerDojo.entryWelfareInfo.residueDay = checkNumber(data.residueDay)
                    playerDojo.entryWelfareInfo.drawStatus = checkNumber(data.drawStatus)
                    playerDojo.entryWelfareInfo.status = checkNumber(data.status)
                    if checkInt(data.status) == 1 then
                        ---开始状态下
                        GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaEntryWelfare, checkNumber(playerDojo.entryWelfareInfo.drawStatus) == 0 and 1 or 0)
                        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaEntryWelfare)
                    end
                    Events.Broadcast(Constants.EventNames.REFRESH_MAID_COFFEE_DATA)
                end
            end)
        end
        if playerDojo and isSet(playerDojo, "consumeCopyActivity") then
            GameUtils.Request(Interfaces.OverseaRegionalMapCopyActivityStatus, {},function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = response.data
                    if isSet(data, "consumeCopyActivity") then
                        playerDojo.consumeCopyActivity = checkTable(data.consumeCopyActivity)
                    end
                end
            end)
        end
    end
    ---@type WhiteLevelGiftComponent
    local whiteLevelGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.WhiteLevelGiftComponent)
    if whiteLevelGiftComponent then
        whiteLevelGiftComponent:SetWhiteLevelGiftTodayReward(0)
    end

    ---@type WhiteLevelGiftComponent
    local MaidCoffeeComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    if MaidCoffeeComponent then
        MaidCoffeeComponent:RequestHomeData()
    end
    xTry(function()
        ---刷新在线奖励
        local isOnlineUnlocked = SystemToggleMgr:GetInstance():IsUnLockModel(Constants.SystemToggleIds.Id9004, true)
        if isOnlineUnlocked then
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if playerComponent then
                local playerDojo = playerComponent.playerDojo
                GameUtils.Request(Interfaces.OverseaOnlineTask, { }, function(request, response)
                    local code = checkNumber(response.errCode)
                    if code == 0 then
                        playerDojo.onlineTaskInfo.unlockStatus = 1
                        playerDojo.onlineTaskInfo.taskList = checkTable(response.data.taskList)
                        ---修改为解锁的状态,更新主界面按钮状态
                        Events.Broadcast("ONLINE_REWARD_BUTTON_EVENT")
                    end
                end)
            end
        end
    end)
end

---@param logType integer
---@param logBody string | table
---@param packetId integer | nil
function AppService:TcpLog(logType, logBody, packetId)
    if not (Config.DEBUG or Config.MAIN_TCP_LOG) then
        return
    end
    xTry(function()
        local socketIndex = checkInt(KNManager.client.protocol.usedIndex)
        if logType == LOG_TYPE.SEND or logType == LOG_TYPE.TAKE then
            if IgnoreLogMap[packetId] then
                return
            end

            local logTitle = string.format('%s %s', tostring(packetId), tostring(PacketNameDict[checkInt(packetId)]))
            local logDetail = ''
            if type(logBody) == 'table' then
                logDetail = table.toString(logBody, '')
            else
                logTitle = string.format('%s : %s', logTitle, checkString(logBody))
            end

            if Config.DEBUG then
                if logType == LOG_TYPE.SEND then
                    print(string.format("<color=#3399CC>[GAME_TCP_SEND:%d] %s</color>%s", socketIndex, logTitle, logDetail))
                else
                    print(string.format("<color=#99CC33>[GAME_TCP_TAKE:%d] %s</color>%s", socketIndex, logTitle, logDetail))
                end
            end
            if Config.MAIN_TCP_LOG then
                if logType == LOG_TYPE.SEND then
                    self:Log2File(string.format("<color=#3399CC>[GAME_TCP_SEND:%d] %s</color>%s", socketIndex, logTitle, logDetail))
                else
                    self:Log2File(string.format("<color=#99CC33>[GAME_TCP_TAKE:%d] %s</color>%s", socketIndex, logTitle, logDetail))
                end
            end
        else
            if Config.DEBUG then
                print(string.format("<color=#CC9933>[GAME_TCP_INFO:%d] %s</color>", socketIndex, tostring(logBody)))
            end
            if Config.MAIN_TCP_LOG then
                self:Log2File(string.format("<color=#CC9933>[GAME_TCP_INFO:%d] %s</color>", socketIndex, tostring(logBody)))
            end
        end
    end)
end

