--@region 常驻活动界面的体力领取
---@param data table data.freeHpNum服务端给的可领取的次数  data.freeHpRestoreTimes服务端给的体力恢复满倒计时
function AppService:SetFreeHpCountDown(data)
    --id从基础参数表中得来
    local max = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 13).num--固定时间赠送的体力可累计次数
    local current = data.freeHpNum--服务端给的可领取的次数
    local recoveryInterval = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 11).num--固定时间（12小时）赠送体力（秒）
    local recoveryAmount = 1 --恢复量，每次恢复一点
    local nextHpSeconds = data.nextFreeHpRecoveryTime--下次一恢复剩余时间  如0-->1剩余时间
    local fullRecoveryTime = data.freeHpRestoreTimes --体力恢复满倒计时  如0——>2剩余时间
    self.recoveryValueFreeHp = RecoveryValue(
            checkNumber(max),
            checkNumber(current),
            checkNumber(recoveryInterval),
            checkNumber(recoveryAmount),
            checkNumber(nextHpSeconds),
            checkNumber(fullRecoveryTime)
    )
    self.recoveryValueFreeHp.OnValueRecovery = function(amount)
        GameUtils.SetRedPointNum(Constants.RedPointConst.PhysicalStrength, self.recoveryValueFreeHp.Current)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.PhysicalStrength)
    end
end

