--@region 每日五点刷新的东西写在这个里面
---@param remainTime number 距离刷新时间的秒数
function AppService:SetDailyRefreshTime(remainTime)
    self:StopDailyTimer()
    remainTime = checkNumber(remainTime)
    if remainTime <= 0 then
        return
    end
    self.dailyTimer = CDTimerModule:AddCD(1, function(count, id)
        if count == 0 then
            --每日一级货币兑换体力次数归零
            ---@type PlayerComponent
            local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            playerComp.playerDojo.buyHpNum = 0
            Events.Broadcast(Constants.EventNames.DailyUpdateData)
            -- 活动刷新
            local activityMgr = import('Game.Activity.ActivityMgr'):GetInstance()
            activityMgr:UpdateActivityHomeData(true)
            -- 刷新主界面抽卡活动
            activityMgr:UpdateHomeGachaActivityData()
            -- 每日任务
            GameUtils.SetRedPointNum(Constants.RedPointConst.DailyTaskBox, 0)
            -- 每日礼包
            GameUtils.UpdateServerRedPointData({ unMallChest = 0 })
            --
            Events.Broadcast(Constants.EventNames.DailyRefresh)
            ---春节去除特殊登录奖励
            local FeatureSignComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FeatureSignComponent)
            if isNotNull(FeatureSignComponent) then
                FeatureSignComponent:RequestFestivalSignInInfo()
            end

            -- 重置刷新时间
            playerComp.playerDojo.dailyRefreshTime = 86400 -- 一天的秒数
            self:SetDailyRefreshTime(playerComp.playerDojo.dailyRefreshTime)--开启下一轮倒计时
        elseif count == 18000 then
            local StoreUtils = import('Game.UI.Store.StoreUtils')
            local comp = StoreUtils.GetStoreComp()
            -- 两种情况 ， 不是最后一天领取和最后一天领取
            if comp:IsHaveDrawRewards() then
                GameUtils.UpdateServerRedPointData({ unFreeHp = 0 })
                Events.Broadcast(Constants.EventNames.OnMonthCardUpdate)
            end
        end
    end, remainTime, true, true, true)
end

