function AppService:TrialUpdateCallback()
    self.elapsedDelta = self.elapsedDelta + RealTime.deltaTime
    if self.elapsedDelta >= COUNT_DOWN_INTERVAL then
        self.elapsedDelta = self.elapsedDelta - COUNT_DOWN_INTERVAL
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComponent then
            local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
            if trialRemainTime > -2 then
                ---执行更新的操作,只进行数据更新
                playerComponent.playerDojo.trialRemainTime = trialRemainTime - COUNT_DOWN_INTERVAL
            else
                playerComponent.playerDojo.trialRemainTime = TRAIL_ALL_TIME - COUNT_DOWN_INTERVAL
                --Events.Broadcast(Constants.EventNames.RefeshTrailStage)
                GameUtils.SetRedPointNum(Constants.RedPointConst.TrailQuestTask, 0)
            end
        end

        if self._isCheckGvgTips and ClubUtils then
            ---@type ClubHomeDojo
            local homeDojo = ClubUtils.GetClubComp():GetHomeDojo()
            local gvgEndTime = homeDojo.gvgEndTime
            if GameUtils.GetServerTime() >= gvgEndTime then
                Events.Broadcast(Constants.EventNames.ClubGVGCloseTips)
            end
            self:SetOpenCheckGvgTipsClose(false)
            
        end
    end
end


