---开始签到的逻辑代码
function AppService:StartSign()
    local isFirstEnterGame = KCookie.Get(Constants.UICacheDataKeys.IS_FIRST_ENTER_SIGN)
    if isNull(isFirstEnterGame) then
        xpcall(function()
            GameUtils.Request(Interfaces.SignHome, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    KCookie.Set(Constants.UICacheDataKeys.IS_FIRST_ENTER_SIGN, 1)
                    ----开始处理数据
                    local t = timestamp_to_time(TimeZoneUtils.UtcSeconds)
                    local curDay = t.day ---当前在这个月中的天值
                    local singData = checkTable(responseData.ftLoginInfo)
                    local giftBoxData = checkTable(responseData.ftLoginRewardInfo)
                    ---消耗信息
                    local consumeInfo = checkTable(responseData.ftLoginCumulativeInfo)
                    local needPopupSign = 0
                    local curDaySignData
                    for _, v in pairs(singData) do
                        if checkNumber(v.day) == curDay and checkNumber(v.hasDrawn) == 0 then
                            ---当前天并且未签，请求登录签，然后才会弹出签到界面
                            curDaySignData = v
                            needPopupSign = 1
                            break
                        end
                    end
                    if needPopupSign == 1 then
                        GameUtils.Request(Interfaces.SignRequest, {}, function(req, resp)
                            if checkNumber(resp.errCode) == 0 then
                                ---请求签到完成
                                if curDaySignData then
                                    curDaySignData.hasDrawn = 2 ---表示是已签到了更新下数据,2用来做动画
                                end
                                local responseData = checkTable(resp.data)
                                GoodsUtils.DrawRewards(checkTable(responseData.rewards))
                                ---可以弹出签到页面了
                                UIModule.OpenDialog({ id = Constants.UITypeIds.PlayerSignDialog, parameters = { signData = singData, giftData = giftBoxData, curDay = curDay, rewards = responseData.rewards, reIssueNum = checkNumber(responseData.reIssueNum), consumeInfo = consumeInfo } })
                            end
                        end)
                    else
                        UIModule.OpenDialog({ id = Constants.UITypeIds.PlayerSignDialog, parameters = { signData = singData, giftData = giftBoxData, curDay = curDay, rewards = responseData.rewards, reIssueNum = checkNumber(responseData.reIssueNum), consumeInfo = consumeInfo } })
                    end
                end
            end)
        end, function(e)
            printError(tostring(e))
        end)
    end
end

