--- 发送消息添加缓存
---@param reqId any
---@param reqData any
function AppService:AddCache(reqId, reqData)
    local needCache = PacketNeedCache[reqId]
    if isNotNull(needCache) and needCache == 1 then
        print("[重发] 添加缓存:", reqId)
        table.insert(self.waitAckQueue, {reqId = reqId, reqData = reqData})
    end
end

--- 收到回复包以后清除缓存
---@param ackId any
function AppService:RemoveCache(ackId)
    local reqId = PacketAckMap[ackId]
    if isNotNull(reqId) then
        local findIndex = -1
        for i, req in ipairs(self.waitAckQueue) do
            if req.reqId == reqId then
                findIndex = i
                break
            end
        end
        if findIndex > 0 then
            print("[重发] 移除缓存:", reqId)
            table.remove(self.waitAckQueue, findIndex)
        end
    end
end

--- 断线重连时重发缓存的消息
function AppService:ResendCache()
    if table.count(self.waitAckQueue) > 0 then
        for i, v in ipairs(self.waitAckQueue) do
            if isNull(v.reqData) then
                v.reqData = {}
            end
            v.reqData.resend = (v.reqData.resend or 0) + 1
            print("[重发] 发送:", v.reqId)
            self:SendTcpData(v.reqId, v.reqData, 1)
        end
    end
end

--- 日志写到文件
---@param msg any
function AppService:Log2File(msg)
    if not Config.MAIN_TCP_LOG then return end

    local preFix = string.format("\n\n[%s][%f] : ", os.date("%m.%d %H:%M:%S", os.time()), os.clock())
    io.writeFile(self.logFilePath, preFix..msg, "a+")
end

--- 删除过期的日志文件
---@param dirPath string 目录
---@param elapsedDays integer 过期时间 天
function AppService:RemoveExpirationLogFile(dirPath, elapsedDays)
    if isNull(dirPath) then return end
    elapsedDays = elapsedDays or 30

    local DateTime = CS.System.DateTime
    local File = CS.System.IO.File
    local Directory = CS.System.IO.Directory

    if not Directory.Exists(dirPath) then return end

    local paths = Directory.GetFiles(dirPath)
    local len = paths.Length
    if len == 0 then return end

    for i = 1, len, 1 do
        local fullPath = paths[i - 1]

        local needRemove = false
        for i, v in ipairs(NeedRemoveLogList) do
            if string.contains(fullPath, v) then
                needRemove = true
                break
            end
        end

        if needRemove then
            local lastWriteTime = File.GetLastWriteTimeUtc(fullPath)
            local deltaDays = checkInt((DateTime.Now - lastWriteTime).TotalDays)
            if deltaDays > elapsedDays then
                File.Delete(fullPath)
            end
        end
    end
end

